#[cfg(test)]
mod conformance {
    //! Round-trip tests harvested from the spec's `spec.md`,
    //! plus a `rejects_invalid_examples` test for any fixtures
    //! in `payload.invalid-examples.json` (validate feature).
    #[test]
    fn request_example_1() {
        const JSON: &str = "{\n  \"id\": \"urn:uuid:00000000-0000-4000-8000-000000000001\",\n  \"type\": \"https://trusttasks.org/spec/vault/credentials/unarchive/0.1#request\",\n  \"issuer\": \"did:example:wallet\",\n  \"recipient\": \"did:example:agent\",\n  \"issuedAt\": \"2026-01-01T00:00:00Z\",\n  \"threadId\": \"urn:uuid:00000000-0000-4000-8000-0000000000ff\",\n  \"payload\": {\n    \"id\": \"cred-7f3a91c2\"\n  }\n}\n";
        let doc: crate::TrustTask<super::Payload> =
            serde_json::from_str(JSON).expect("deserialize request example");
        let rendered = serde_json::to_value(&doc).expect("re-serialize");
        let expected: serde_json::Value = serde_json::from_str(JSON).expect("re-parse expected");
        assert_eq!(rendered, expected, "request example failed round-trip");
    }
    #[test]
    fn response_example_1() {
        const JSON: &str = "{\n  \"id\": \"urn:uuid:00000000-0000-4000-8000-000000000002\",\n  \"type\": \"https://trusttasks.org/spec/vault/credentials/unarchive/0.1#response\",\n  \"issuer\": \"did:example:agent\",\n  \"recipient\": \"did:example:wallet\",\n  \"issuedAt\": \"2026-01-01T00:00:01Z\",\n  \"threadId\": \"urn:uuid:00000000-0000-4000-8000-0000000000ff\",\n  \"payload\": {\n    \"id\": \"cred-7f3a91c2\",\n    \"lifecycle\": \"active\"\n  }\n}\n";
        let doc: crate::TrustTask<super::Response> =
            serde_json::from_str(JSON).expect("deserialize response example");
        let rendered = serde_json::to_value(&doc).expect("re-serialize");
        let expected: serde_json::Value = serde_json::from_str(JSON).expect("re-parse expected");
        assert_eq!(rendered, expected, "response example failed round-trip");
    }
    /// Each fixture in `payload.invalid-examples.json` MUST be
    /// rejected by at least one of: serde deserialization, or
    /// JSON-Schema validation under the `validate` feature. The
    /// fixture file documents the producer-side bug class that
    /// each payload exemplifies; this generated test pins it.
    #[cfg(feature = "validate")]
    #[test]
    fn rejects_invalid_examples() {
        use crate::validate::ValidatedPayload;
        let fixtures: &[(&str, &str)] = &[
            (
                "Missing `id`. There is no default credential, and an absent id must not read as 'all of them'.",
                "{}",
            ),
            (
                "Empty `id`. minLength guards the shape that would otherwise reach a maintainer's storage layer as a prefix scan.",
                "{\n  \"id\": \"\"\n}",
            ),
            (
                "Unbounded `reason` — §7.3 item 19. The member lands in an audit trail; maxLength is what keeps a write there bounded.",
                "{\n  \"id\": \"cred-1\",\n  \"reason\": \"\"\n}",
            ),
            (
                "Bare/unnamespaced ext key — SPEC §4.5.1 requires every immediate child of ext to be reverse-DNS namespaced.",
                "{\n  \"ext\": {\n    \"bare-key\": {\n      \"anything\": \"here\"\n    }\n  },\n  \"id\": \"cred-1\"\n}",
            ),
            (
                "Unknown top-level member — additionalProperties: false catches `lifecycle`. A consumer names the credential and the verb; it does not assert the resulting state.",
                "{\n  \"id\": \"cred-1\",\n  \"lifecycle\": \"archived\"\n}",
            ),
            (
                "`force` on a task that has no forced form. Only `delete` distinguishes tombstone from erase; accepting it here would silently ignore a caller asking for something stronger.",
                "{\n  \"force\": true,\n  \"id\": \"cred-1\"\n}",
            ),
        ];
        for (i, (note, raw)) in fixtures.iter().enumerate() {
            let value: serde_json::Value = match serde_json::from_str(raw) {
                Ok(v) => v,
                Err(_) => continue,
            };
            let serde_ok = serde_json::from_value::<super::Payload>(value.clone()).is_ok();
            let schema_ok = super::Payload::validate_value(&value).is_ok();
            assert!(
                !(serde_ok && schema_ok),
                "invalid-example #{} ({:?}) was accepted by both serde and JSON Schema; \
                         the fixture's stated failure class is no longer caught:\n{}",
                i + 1,
                note,
                raw
            );
        }
    }
}
